// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.valueoverlay;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.concurrent.CancellationException;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

/** Admission follows physical ownership across publication retirement and concurrent maintenance. */
class ValueOverlayMemoryLifecycleTest {
	private static final int REVERSE_SLOTS = 1 << 20;
	// Two reverse tables alone exceed this budget, even before directories and builder workspace.
	private static final long SHARED_LIMIT = 2L * REVERSE_SLOTS * Long.BYTES - 1;
	private static final byte[] RECORD = { 1, 5, 0, 's', 't', 'a', 'b', 'l', 'e' };
	private static final CompressedValueOverlay.Options OPTIONS = new CompressedValueOverlay.Options(
			32L << 20, REVERSE_SLOTS, 4, 1024, 1 << 20, true, true);

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void nestedSnapshotLeasesRetainTheirChargeAfterInvalidationOrClose(boolean close) {
		OverlayMemoryBudget budget = new OverlayMemoryBudget(SHARED_LIMIT);
		try (ValueOverlayRegistry first = registry(budget); ValueOverlayRegistry second = registry(budget)) {
			publish(first);
			try (ValueOverlayRegistry.SnapshotLease outer = first.acquireSnapshot(1)) {
				assertNotNull(outer);
				try (ValueOverlayRegistry.SnapshotLease inner = first.acquireSnapshot(1)) {
					assertNotNull(inner);
					retire(first, close);
					assertFalse(first.isPopulated());
					assertRefusedBuilderReleasesItsCharges(second, budget);
					assertArrayEquals(RECORD, inner.get(1));
					assertArrayEquals(RECORD, outer.get(1));
				}
				assertTrue(budget.stats().nativeBytes() >= REVERSE_SLOTS * (long) Long.BYTES);
				assertArrayEquals(RECORD, outer.get(1));
			}
			assertEquals(0, budget.stats().used());
			publish(second);
			try (ValueOverlayRegistry.SnapshotLease replacement = second.acquireSnapshot(1)) {
				assertNotNull(replacement);
				assertArrayEquals(RECORD, replacement.get(1));
			}
		}
		assertEquals(0, budget.stats().used());
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void activeCompactionRetainsItsBaseAfterInvalidationOrClose(boolean close) throws Exception {
		OverlayMemoryBudget budget = new OverlayMemoryBudget(SHARED_LIMIT);
		try (ValueOverlayRegistry first = registry(budget); ValueOverlayRegistry second = registry(budget)) {
			publish(first);
			commit(first, 2);
			commit(first, 3);
			try (ValueOverlayRegistry.Compaction compaction = first.prepareCompaction()) {
				assertNotNull(compaction);
				retire(first, close);
				assertFalse(first.isPopulated());
				assertRefusedBuilderReleasesItsCharges(second, budget);
				if (close) {
					assertThrows(CancellationException.class, compaction::build);
				} else {
					compaction.build();
					assertFalse(compaction.publish(), "invalidated maintenance must never restore an old publication");
				}
			}
			assertEquals(0, budget.stats().used());
			publish(second);
		}
		assertEquals(0, budget.stats().used());
	}

	@Test
	void repeatedSharedAdmissionRefusalsPreserveAnotherStoresPublishedView() {
		OverlayMemoryBudget budget = new OverlayMemoryBudget(SHARED_LIMIT);
		try (ValueOverlayRegistry first = registry(budget); ValueOverlayRegistry second = registry(budget)) {
			publish(first);
			for (int attempt = 0; attempt < 3; attempt++) {
				assertRefusedBuilderReleasesItsCharges(second, budget);
				try (ValueOverlayRegistry.SnapshotLease original = first.acquireSnapshot(1)) {
					assertNotNull(original);
					assertArrayEquals(RECORD, original.get(1));
				}
			}
			assertEquals(3, budget.stats().refusals());
			first.invalidate();
			assertEquals(0, budget.stats().used());
			publish(second);
		}
		assertEquals(0, budget.stats().used());
	}

	@Test
	void partiallyAllocatedBuilderRefusalPreservesAnotherStoresPublishedView() {
		OverlayMemoryBudget budget = new OverlayMemoryBudget(SHARED_LIMIT);
		try (ValueOverlayRegistry first = registry(budget); ValueOverlayRegistry second = registry(budget)) {
			publish(first);
			OverlayMemoryBudget.Stats before = budget.stats();
			CompressedValueOverlay.Options small = new CompressedValueOverlay.Options(
					1 << 16, 0, 1, 1024, 1 << 20, false, false);
			assertThrows(OverlayCapacityException.class, () -> {
				try (CompressedValueOverlay.Builder candidate = second.newBaseBuilder(small)) {
					candidate.add(2, RECORD, RecordFamily.TEXT, 0, false);
					assertTrue(budget.stats().nativeBytes() > before.nativeBytes());
					byte[] large = new byte[(1 << 16) + 1];
					large[0] = 1;
					large[1] = 5;
					candidate.add(3, large, RecordFamily.TEXT, 0, false);
					candidate.finish();
				}
			});
			assertChargesEqual(before, budget.stats());
			try (ValueOverlayRegistry.SnapshotLease original = first.acquireSnapshot(1)) {
				assertNotNull(original);
				assertArrayEquals(RECORD, original.get(1));
			}
		}
		assertEquals(0, budget.stats().used());
	}

	private static ValueOverlayRegistry registry(OverlayMemoryBudget budget) {
		return new ValueOverlayRegistry(new ValueOverlayRegistry.DeltaOptions(1 << 18, 8, 4, 4), budget);
	}

	private static void publish(ValueOverlayRegistry registry) {
		try (CompressedValueOverlay.Builder builder = registry.newBaseBuilder(OPTIONS)) {
			builder.add(1, RECORD, RecordFamily.TEXT, 0, true);
			assertTrue(registry.publish(new Object(), 1, builder.finish(), () -> true));
		}
	}

	private static void commit(ValueOverlayRegistry registry, long transactionId) throws Exception {
		try (ValueOverlayRegistry.Mutation mutation = registry.begin(transactionId)) {
			assertNotNull(mutation);
			mutation.touch(transactionId);
			assertTrue(registry.complete(mutation.prepare(id -> new ValueOverlayRegistry.Record(RECORD, true)),
					transactionId));
		}
	}

	private static void retire(ValueOverlayRegistry registry, boolean close) {
		if (close) {
			registry.close();
		} else {
			registry.invalidate();
		}
	}

	private static void assertRefusedBuilderReleasesItsCharges(ValueOverlayRegistry registry,
			OverlayMemoryBudget budget) {
		OverlayMemoryBudget.Stats before = budget.stats();
		assertThrows(OverlayCapacityException.class, () -> registry.newBaseBuilder(OPTIONS));
		assertChargesEqual(before, budget.stats());
	}

	private static void assertChargesEqual(OverlayMemoryBudget.Stats expected, OverlayMemoryBudget.Stats actual) {
		assertEquals(expected.limit(), actual.limit());
		assertEquals(expected.used(), actual.used());
		assertEquals(expected.nativeBytes(), actual.nativeBytes());
		assertEquals(expected.retainedHeapBytes(), actual.retainedHeapBytes());
		assertEquals(expected.workspaceBytes(), actual.workspaceBytes());
	}
}
